# Write out the translated_blocks.json database
translated_blocks = []
try:
    with open("scratch/blocks_to_translate.json", "r", encoding="utf-8") as f:
        blocks_data = json.load(f)
except FileNotFoundError:
    blocks_data = []

print(f"Loaded {len(blocks_data)} blocks from template.")
mapped_count = 0
for b in blocks_data:
    eng_text = b["eng"].strip()
    eng_key = b["eng"]
    
    trans_html = translations.get(eng_key)
    if not trans_html:
        trans_html = translations.get(eng_text)
        
    if trans_html:
        b["vn"] = trans_html
        mapped_count += 1
    else:
        # fallback to english if not defined yet
        b["vn"] = b["eng"]
        print(f"WARNING: Not translated key: {b['eng'][:100]}...")

print(f"Mapped {mapped_count}/{len(blocks_data)} blocks.")

with open("scratch/translated_blocks.json", "w", encoding="utf-8") as f:
    json.dump(blocks_data, f, ensure_ascii=False, indent=2)

print("Wrote output to scratch/translated_blocks.json")
